import { defineSchema, defineTable } from "convex/server";
import { v } from "convex/values";

export default defineSchema({
  presence: defineTable({
    user_id: v.string(),
    updated_at: v.number(),
  }).index("by_user_id", ["user_id"]),
});

import { mutation, query } from "./_generated/server";
import { v } from "convex/values";

export const heartbeat = mutation({
  args: { user_id: v.string() },
  handler: async (ctx, args) => {
    const existing = await ctx.db
      .query("presence")
      .withIndex("by_user_id", (q) => q.eq("user_id", args.user_id))
      .first();

    const now = Date.now();
    if (existing) {
      await ctx.db.patch(existing._id, { updated_at: now });
    } else {
      await ctx.db.insert("presence", {
        user_id: args.user_id,
        updated_at: now,
      });
    }
  },
});

export const getOnlineUsers = query({
  args: {},
  handler: async (ctx) => {
    const now = Date.now();
    const threshold = now - 15000; // 15 seconds ago

    const allPresence = await ctx.db.query("presence").collect();

    // Filter and sort manually since we don't have an index on updated_at
    // Or we could add an index, but this is fine for this task
    return allPresence
      .filter((p) => p.updated_at >= threshold)
      .map((p) => p.user_id);
  },
});

import { useState, useEffect } from 'react'
import { useQuery, useMutation } from "convex/react"
import { api } from "../convex/_generated/api"
import './App.css'

function App() {
  const [userId, setUserId] = useState('')
  const [isOnline, setIsOnline] = useState(false)
  const heartbeat = useMutation(api.presence.heartbeat)
  const onlineUsers = useQuery(api.presence.getOnlineUsers) || []

  useEffect(() => {
    let interval: NodeJS.Timeout;

    if (isOnline && userId) {
      // Send immediate heartbeat
      heartbeat({ user_id: userId }).catch(console.error);

      // Setup interval
      interval = setInterval(() => {
        heartbeat({ user_id: userId }).catch(console.error);
      }, 5000);
    }

    return () => {
      if (interval) clearInterval(interval);
    }
  }, [isOnline, userId, heartbeat]);

  const handleGoOnline = () => {
    if (userId.trim()) {
      setIsOnline(true)
    }
  }

  return (
    <div style={{ padding: '20px' }}>
      <h1>Real-time Presence</h1>

      <div style={{ marginBottom: '20px' }}>
        <input 
          type="text" 
          placeholder="Enter User ID" 
          value={userId}
          onChange={(e) => setUserId(e.target.value)}
          disabled={isOnline}
        />
        <button 
          onClick={handleGoOnline}
          disabled={isOnline || !userId.trim()}
          style={{ marginLeft: '10px' }}
        >
          {isOnline ? 'Online' : 'Go Online'}
        </button>
      </div>

      <div>
        <h2>Online Users</h2>
        <ul>
          {onlineUsers.map((user) => (
            <li key={user} data-testid="online-user">
              {user}
            </li>
          ))}
        </ul>
      </div>
    </div>
  )
}

export default App
